struct Noisy(&'static str);

impl Drop for Noisy {
    fn drop(&mut self) {
        println!("drop {}", self.0);
    }
}

fn take(n: Noisy) {
    println!("take got {}", n.0);
}

fn main() {
    let a = Noisy("a");
    let b = Noisy("b");
    take(b);
    let v = vec![Noisy("v1"), Noisy("v2")];
    let a = Noisy("a2"); // shadows a; the first a is still alive
    {
        let _c = Noisy("c");
    }
    println!("end of main ({} items in v, a is {})", v.len(), a.0);
}
